    if step_count < 110:
        gx, gy = 11.95, 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        # Move towards activation zone center (13.5, 1.35)
        gx = 13.5
        gy = 1.35

    # Calculate target direction
    target_dir = math.atan2(ty - sy, tx - sx)
    target_speed = math.hypot(state['tvx'], state['tvy'])

    # Calculate desired heading
    if target_speed >= 0.15:
        desired_heading = target_dir
    else:
        desired_heading = math.atan2(ty - sy, tx - sx)

    # Track activation zone
    if 13.0 <= sx <= 17.0:
        state['activation_steps'] += 1
    else:
        state['activation_steps'] = 0
    if state['activation_steps'] >= 80:
        state['activation_achieved'] = True

    # Handle cooldown
    if state['cooldown_steps'] > 0:
        state['cooldown_steps'] -= 1
        if state['cooldown_steps'] == 0:
            max_thrust = 95.0
        else:
            max_thrust = 20.0
    else:
        max_thrust = 95.0

    # Calculate force based on slot status
    if in_slot:
        # Adjusted coefficients for new thrust limits
        fx = 100.0 * (gx - sx) + 20.0 * (state['tvx'] - svx)
        fy = 80.0 * (gy - sy) + 10.0 * (state['tvy'] - svy)
    else:
        # Move towards activation zone center
        fx = 100.0 * (gx - sx) - 20.0 * svx
        fy = 80.0 * (gy - sy) - 10.0 * svy

    # Apply heading constraints
    heading_error = (desired_heading - state['angle']) % (2 * math.pi)
    if heading_error > math.pi:
        heading_error = -heading_error

    if abs(heading_error) > 0.12:
        # Limit heading rotation rate
        heading_rotation = 0.12
        desired_angle = state['angle'] + heading_rotation * (1 if heading_error > 0 else -1)
        state['angle'] = desired_angle

        # Adjust force to align with desired heading
        angle_diff = desired_angle - state['angle']
        if angle_diff > math.pi:
            angle_diff -= 2 * math.pi
        if angle_diff < -math.pi:
            angle_diff += 2 * math.pi
        fx, fy = math.cos(angle_diff) * fx, math.sin(angle_diff) * fy

    # Normalize force magnitude
    mag = math.hypot(fx, fy)
    if mag > max_thrust:
        fx, fy = fx * max_thrust / mag, fy * max_thrust / mag

    # Check if thrust exceeds 90 N to trigger cooldown
    if mag > 90.0:
        state['cooldown_steps'] = 120
        max_thrust = 20.0

    # Apply force
    sandbox.apply_seeker_force(fx, fy)

